  auto result=std::make_shared<CommitResult>();result->result_id="result:10";result->kind=kind;result->tick=c.tick();result->revision=c.revision();ReceiptData payload=Done{};if(kind=="wait"){AdvanceDetails advance;ActionCompletion done;done.completed=true;done.success=true;advance.completed_actions.insert("action:2",done);payload=advance;}if(kind=="duel_start")payload=PersonalReceipt{"battle:7",{},{}};result->details=std::make_shared<ReceiptDetails>(ReceiptDetails{payload,{}});const StableId outer=cancel?"student":"visitor";const Integer seq=cancel?3:1;c.state().request_sequences.set(outer,seq);c.state().results.insert(outer+":"+std::to_string(seq),result);c.state().history.push_back({c.tick(),kind,outer,result->result_id,{}});check(bind_growth_tactic_lesson_result_in_candidate(c,lesson,{{},{"tactic_lesson:9"}},outer,seq,*result,7).ok,"actual outer result and clock bind");
  step.phase=cancel?PlayerPlanStepPhase::blocked:PlayerPlanStepPhase::completed;step.completed_tick=c.tick();step.completion_result_id=result->result_id;step.stop_reason=cancel?"TacticLessonStudentCancelled":"";plan.steps.push_back(step);
  auto exact=player_plan_tactic_lesson_completion(c,lesson,"student","action:2",*result);check(exact.ok&&exact.value&&exact.value->success==!cancel,"exact student completion from outer writer");check(validate_player_plan(c,state,&lesson).ok,"new profile accepts only exact source-backed terminal");
